// app/page.tsx - 首页页面组件
// 只有 page.tsx 才会生成路由入口
export default function HomePage() {
  return (
    <main>
      <h1>欢迎来到 Next.js</h1>
      <p>这是首页，由 app/page.tsx 渲染</p>
    </main>
  )
}

