// app/about/page.tsx - 关于页
// 目录层级即 URL 路径层级
export default function AboutPage() {
  return (
    <div>
      <h1>关于我们</h1>
      <p>Next.js App Router 示例</p>
    </div>
  )
}

// ============================================

// app/loading.tsx - 全局加载状态
// 路由切换时自动显示
export default function Loading() {
  return <div className="loading">加载中...</div>
}

