export default function BlogPage() {
  return <h1>博客列表</h1>
}

// ============================================

// app/blog/[slug]/page.tsx - 动态路由 /blog/:slug
// 方括号表示动态参数
export default function BlogPostPage({
  params,
}: {
  params: { slug: string }
}) {
  return <h1>文章：{params.slug}</h1>
}

// ============================================

// app/docs/[...slug]/page.tsx - Catch-all 路由 /docs/a/b/c
// params.slug 是数组 ['a', 'b', 'c']
export default function DocsPage({
  params,
}: {
  params: { slug: string[] }
}) {
  return <h1>文档路径：{params.slug.join(' / ')}</h1>
}

// ============================================

// app/shop/[[...slug]]/page.tsx - 可选 Catch-all
// 匹配 /shop、/shop/a、/shop/a/b 等
export default function ShopPage({
  params,
}: {
  params: { slug?: string[] }
}) {
  const path = params.slug?.join(' / ') || '首页'
  return <h1>商店：{path}</h1>
}

// ============================================

// app/(marketing)/about/page.tsx - 路由组
// URL 仍是 /about，(marketing) 不影响路径
// 可用于组织代码和独立布局
export default function AboutPage() {
  return <h1>关于我们</h1>
}

// ============================================

// app/_components/Button.tsx - 私有文件夹
// _ 前缀的文件夹不参与路由生成
// 用于存放内部组件和工具函数
'use client'

export function Button({ children }: { children: React.ReactNode }) {
  return <button className="btn">{children}</button>
}`),language:"jsx",principle:"App Router 基于文件系统生成路由：page.tsx 定义页面 UI，目录层级即 URL 层级。方括号 [param] 表示动态参数，[...slug] 捕获多段，[[...slug]] 可选捕获；圆括号 (group) 是路由组（不影响路径），@ 前缀是并行路由插槽，_ 前缀是私有文件夹（不参与路由）。",flow:["理解只有 page.tsx 会产生路由，目录仅是路径段。","区分 [param]、[...slug]、[[...slug]] 三种动态参数写法。","认识 (group) 路由组、@ 插槽、_ 私有文件夹的命名作用。"],notes:["page.tsx 之外的文件（layout/loading/error 等）不直接生成路由。","[[...slug]] 是可选 Catch-all，零个路径段也会匹配。","(group) 只影响代码组织与布局，不改变最终 URL。"],problem:'解决"Next.js 文件名各种括号和符号代表什么、如何用文件结构表达复杂路由"的问题。'},{id:"X_3",title:"布局与模板：共享 UI 的层级",navTitle:"布局模板",category:"起步",path:"/nextjs/x-3/layouts",summary:"理解根布局、嵌套布局、路由组布局和 template 的区别与嵌套机制。",demo:s,code:()=>Promise.resolve(`// app/layout.tsx - 根布局（最外层）
