'use client'

import { useState } from 'react'

export default function BlogTemplate({
  children,
}: {
  children: React.ReactNode
}) {
  // 每次进入新文章，这个状态都会重置
  const [views, setViews] = useState(0)

  return (
    <div className="blog-template">
      <p>浏览次数：{views}</p>
      {children}
    </div>
  )
}

