const nextConfig = {
  output: 'export', // 纯静态导出
  images: {
    unoptimized: true, // 静态导出需要关闭图片优化
  },
}

module.exports = nextConfig

// 构建命令：
// pnpm next build
// 生成 out/ 目录，包含所有静态文件

// 部署：
